import { SectionType, VoronoiShuffle } from "#base/scripts/voronoi_maps/shuffle.js";

export class VoronoiTerraIncognita extends VoronoiShuffle {
	constructor() {
		super();
		this.m_ruleSetKeysToPlayerRegionIdMap = new Map<string, number>();
		this.m_playerLandmassIdRemap = new Map<number, Map<number, number>>();
	}

	public override simulateInternal(): void {
		super.simulateInternal();
	}

	protected override getSectionWeights(): number[] {
		const weights = super.getSectionWeights();
		// Make the likelihood of getting two continents equal to shuffle despite forcing the first section to be a continent.
		const doubleContinentsRatio = 1 / (weights.length + 1);
		weights[SectionType.Continents] *= doubleContinentsRatio;
		return weights;
	}

	protected override getSectionTypes(count: number): SectionType[] {
		const sectionTypes: SectionType[] = super.getSectionTypes(count);
		sectionTypes[0] = SectionType.Continents; // Terra Incognita always has a continent section, but the rest is shuffled
		return sectionTypes;
	}

	public override simulate() {
		this.m_ruleSetKeysToPlayerRegionIdMap!.clear();
		this.m_playerLandmassIdRemap!.clear();

		super.simulate();

		// After simulation, update the m_ruleSetKeysToPlayerRegionIdMap based on the remap from m_playerRegionRemap
		const originalMap = new Map(this.m_ruleSetKeysToPlayerRegionIdMap!);
		for (const [newPlayerRegionId, oldPlayerRegionMap] of this.m_playerLandmassIdRemap!.entries()) {
			for (const oldPlayerRegionId of oldPlayerRegionMap.keys()) {
				// Find the rule set key associated with the old player region ID
				const entries = Array.from(originalMap.entries());
				const ruleSetKey = entries.find(([_, value]) => value === oldPlayerRegionId)?.[0];
				if (ruleSetKey) {
					console.log(
						`Remapping rule set key ${ruleSetKey} from old player region ID ${oldPlayerRegionId} to new player region ID ${newPlayerRegionId}.`,
					);
					this.m_ruleSetKeysToPlayerRegionIdMap!.set(ruleSetKey, newPlayerRegionId);
				}
			}
		}
	}

	public getContinentPlayerRegionId(): number {
		return (this.m_ruleSetKeysToPlayerRegionIdMap!.get("Continents") ?? 0) - 1; // Adjust for 0-based indexing
	}

	static getName(): string {
		return "Terra Incognita";
	}
}
